inline QString translatedEditorText(const QString& text){return editorEnglish()?editorTranslations().value(text).toString(text):text;}
inline void applyEditorLanguage(QWidget* root){
    auto translate=[](QObject* owner,const QString& current,const char* key){
        const auto& translations=editorTranslations();
        if(translations.contains(current)){owner->setProperty(key,current);return editorEnglish()?translations.value(current).toString():current;}
        const auto original=owner->property(key).toString();
        if(!editorEnglish()&&!original.isEmpty()&&translations.value(original).toString()==current)return original;
        return current;
    };
    auto widgets=root->findChildren<QWidget*>();widgets.prepend(root);
    for(auto* widget:widgets){
        if(auto* label=qobject_cast<QLabel*>(widget)){if(label->pixmap().isNull())label->setText(translate(label,label->text(),"_sourceLabel"));}
        else if(auto* button=qobject_cast<QAbstractButton*>(widget))button->setText(translate(button,button->text(),"_sourceButton"));
        else if(auto* combo=qobject_cast<QComboBox*>(widget)){
            if(combo->objectName()=="settingsLanguage")continue;
            QSignalBlocker guard(combo);
            for(int i=0;i<combo->count();++i){
                const auto text=combo->itemText(i);const auto original=combo->itemData(i,Qt::UserRole+64).toString();
                if(editorTranslations().contains(text)){combo->setItemData(i,text,Qt::UserRole+64);combo->setItemText(i,translatedEditorText(text));}
                else if(!editorEnglish()&&!original.isEmpty())combo->setItemText(i,original);
            }
        }
        if(auto* edit=qobject_cast<QLineEdit*>(widget))edit->setPlaceholderText(translate(edit,edit->placeholderText(),"_sourcePlaceholder"));
        if(auto* edit=qobject_cast<QTextEdit*>(widget))edit->setPlaceholderText(translate(edit,edit->placeholderText(),"_sourcePlaceholder"));
    }
    for(auto* action:root->findChildren<QAction*>())action->setText(translate(action,action->text(),"_sourceAction"));
}
